/* Private workspace. Every private read and write is also authorized by the server. */
const adminKinds={formation:'Formation',document:'Document de la boutique',resource:'Ressource de bibliothèque',article:'Article du blog',event:'Événement',live:'Vidéo',trainer:'Formateur',plan:'Abonnement',watch:'Veille juridique'};
const publicationLabels={draft:'Brouillon',published:'Publié',archived:'Retiré du site'};
const orderLabels={pending_payment:'En attente de paiement',processing:'En cours de traitement',completed:'Traitée',cancelled:'Annulée'};
const managedSections=['formations','boutique','bibliotheque','blog','etudiants','professionnels','entreprises'];
const primarySection={formation:'formations',document:'boutique',resource:'bibliotheque',article:'blog'};
function inSection(item,key,sub=''){return (item.placements||[]).some(p=>p.section===key&&(!sub||p.category===sub))||(primarySection[item.kind]===key&&(!sub||item.category===sub));}
const originalAdmin=adminPage;
function adminLayout(tab){return banner('Administration','Votre espace privé pour piloter le site et publier les contenus du cabinet.')+`<section class="wrap page-content admin-workspace"><nav class="admin-tabs" aria-label="Navigation administration">${(state.user.role==='editor'?['Contenus','Mon profil']:['Tableau de bord','Contenus','Corbeille','Commandes','Demandes','Newsletter',...(state.user.role==='owner'?['Utilisateurs']:[]),'Mon profil']).map(t=>`<a class="btn ${tab===t?'':'outline'}" href="#/administration?onglet=${enc(t)}"${tab===t?' aria-current="page"':''}>${t}</a>`).join('')}</nav><div id="admin-content"></div></section>`;}
adminPage=async function(params){
 if(!state.user){adminAccess();return;}
 if(!['owner','admin','editor'].includes(state.user.role)){main.innerHTML=banner('Accès réservé')+`<section class="wrap section"><p>Ce compte ne dispose pas des droits d’administration.</p>${button('Mon compte','#/compte')}</section>`;return;}
 const tab=params.get('onglet')||(state.user.role==='editor'?'Contenus':'Tableau de bord');
 if(state.user.role==='editor'&&!['Contenus','Mon profil'].includes(tab)){main.innerHTML=adminLayout('Contenus');$('#admin-content').textContent='Votre rôle donne accès uniquement aux contenus et à votre profil.';return;}
 if(['Utilisateurs','Mon profil'].includes(tab)){await securityPage(tab);return;}
 if(['Demandes','Newsletter'].includes(tab)){await originalAdmin(params);return;}
 const token=pageToken;const [d,stats]=await Promise.all([api('admin'),state.user.role==='editor'?Promise.resolve({}):api('admin/overview?days='+(params.get('jours')||'30'))]);if(token!==pageToken)return;
 main.innerHTML=adminLayout(tab);
 const box=$('#admin-content');
 if(tab==='Tableau de bord'){
  box.innerHTML=`<div class="account-heading"><h2>Fréquentation & activité</h2><label>Période <select id="stats-period">${[7,30,90].map(n=>`<option value="${n}" ${n===stats.days?'selected':''}>${n} derniers jours</option>`).join('')}</select></label></div><div class="admin-metrics">${[[stats.totals.visitors,'Visiteurs mesurés'],[stats.totals.sessions,'Sessions'],[stats.totals.views,'Pages vues'],[d.orders.filter(o=>['pending_payment','processing'].includes(o.status)).length,'Commandes à traiter']].map(([n,l])=>`<article><strong>${n}</strong><span>${l}</span></article>`).join('')}</div><p class="muted">La mesure commence à son activation et concerne les visiteurs qui l’acceptent. Un visiteur correspond à un navigateur, pas nécessairement à une personne. Les visites des administrateurs sont exclues.</p><div class="two-col admin-panels"><section><h2>Pages les plus consultées</h2>${stats.pages.length?`<div class="table-scroll"><table><thead><tr><th>Page</th><th>Vues</th><th>Visiteurs</th></tr></thead><tbody>${stats.pages.map(p=>`<tr><td>${esc(pageName(p.page))}</td><td>${p.views}</td><td>${p.visitors}</td></tr>`).join('')}</tbody></table></div>`:'<p>Aucune visite mesurée pour le moment.</p>'}</section><section><h2>Navigation des visiteurs</h2><p>Liens internes suivis depuis les pages publiques.</p>${stats.clicks.map(p=>`<div class="list-row"><span>${esc(pageName(p.page))} → ${esc(pageName(p.target))}</span><b>${p.clicks}</b></div>`).join('')||'<p>Aucun clic mesuré pour le moment.</p>'}</section></div><h2>Évolution quotidienne</h2>${stats.daily.length?`<div class="admin-chart">${stats.daily.map(p=>`<div><span>${esc(p.day)}</span><meter min="0" max="${Math.max(...stats.daily.map(x=>x.views),1)}" value="${p.views}"></meter><span>${p.views} vues · ${p.visitors} visiteurs</span></div>`).join('')}</div>`:'<p>Les premières visites apparaîtront ici.</p>'}<p>Temps actif moyen mesuré par session : ${stats.totals.sessions?Math.round(stats.totals.seconds/stats.totals.sessions):0} secondes.</p>`;
  $('#stats-period').onchange=e=>location.hash='#/administration?jours='+e.target.value;return;
 }
 if(tab==='Corbeille'){
  const archived=d.items.filter(i=>i.status==='archived');
  box.innerHTML=`<div class="account-heading"><div><h2>Corbeille</h2><p>Les contenus retirés du site restent ici jusqu’à leur restauration.</p></div></div>${archived.length?archived.map(i=>`<div class="list-row"><div><h3>${esc(i.title)}</h3><p>${adminKinds[i.kind]} · ${esc(i.category)} · Retiré du site</p></div><button class="text-link" data-archive="${esc(i.id)}" data-restore="true">Restaurer et publier</button></div>`).join(''):'<p>Aucun contenu dans la corbeille.</p>'}`;
  $$('[data-archive]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('admin/archive',{id:b.dataset.archive,restore:true});await refresh();await render();toast('Contenu restauré et publié.');}catch(err){toast(err.message);b.disabled=false;}}); return;
 }
 if(tab==='Commandes'){
  box.innerHTML=`<div class="account-heading"><h2>Suivi des commandes</h2><label>Afficher <select id="order-filter"><option value="">Toutes les commandes</option>${Object.entries(orderLabels).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label></div><p class="notice">Le traitement est administratif : aucun encaissement ni accès payant n’est déclenché par un changement de statut.</p><div id="order-list"></div>`;
  const draw=()=>{$('#order-list').innerHTML=stats.orders.filter(o=>!$('#order-filter').value||o.status===$('#order-filter').value).map(o=>`<article class="admin-order"><div class="account-heading"><div><h3>Commande ${esc(o.id.slice(0,10))}</h3><p>${esc(o.name)} · ${esc(o.email)} · ${date(o.created)}</p></div><strong>${money(o.total)}</strong></div><ul>${o.lines.map(l=>`<li>${esc(l.title)} — ${l.quantity} × ${money(l.price)}</li>`).join('')}</ul><form data-order-id="${esc(o.id)}"><div class="form-grid"><label>Statut<select name="status">${Object.entries(orderLabels).map(([v,l])=>`<option value="${v}" ${v===o.status?'selected':''}>${l}</option>`).join('')}</select></label><label>Note interne<textarea name="note" maxlength="3000" placeholder="Suivi, échange avec le client, prochaine action…"></textarea></label></div><button class="btn small">Enregistrer le traitement</button><div class="feedback" role="status"></div></form>${o.history.length?`<details><summary>Historique du traitement</summary>${o.history.map(h=>`<p>${date(h.created)} · ${orderLabels[h.status]}<br>${esc(h.note)}</p>`).join('')}</details>`:''}</article>`).join('')||'<p>Aucune commande pour cette sélection.</p>';$$('[data-order-id]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const b=$('button',f);b.disabled=true;try{await api('admin/order',{id:f.dataset.orderId,...Object.fromEntries(new FormData(f))});toast('Traitement enregistré.');await render();}catch(err){feedback(f,err.message,true);}finally{b.disabled=false;}});};$('#order-filter').onchange=draw;draw();return;
 }
 box.innerHTML=`<div class="account-heading"><div><h2>Gérer les contenus</h2><p>Publiez, modifiez ou retirez les contenus de chaque rubrique.</p></div><button class="btn" id="new-item">Ajouter un contenu</button></div><div class="admin-filters"><label>Page<select id="content-section"><option value="">Toutes les pages</option>${managedSections.map(k=>`<option value="${k}">${labels[k]}</option>`).join('')}</select></label><label>Publication<select id="content-status"><option value="">Tous les statuts</option>${Object.entries(publicationLabels).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label>Rechercher<input id="content-search" placeholder="Titre ou rubrique"></label></div><div id="content-list"></div><p style="margin-top:24px"><a class="btn outline" href="#/administration?onglet=Corbeille">Ouvrir la corbeille</a></p>`;
 const draw=()=>{const section=$('#content-section').value,status=$('#content-status').value,q=$('#content-search').value.toLocaleLowerCase('fr');const list=d.items.filter(i=>i.status!=='archived'&&(!section||inSection(i,section))&&(!status||i.status===status)&&(!q||(i.title+' '+i.category).toLocaleLowerCase('fr').includes(q)));$('#content-list').innerHTML=`<p class="muted">${list.length} contenu(s)</p>`+list.map(i=>`<div class="list-row"><div><h3>${esc(i.title)}</h3><p>${adminKinds[i.kind]} · ${esc(i.category)} · <b>${publicationLabels[i.status]}</b>${i.demo?' · Exemple':''}</p><p class="tiny">${[...new Set([primarySection[i.kind],...(i.placements||[]).map(p=>p.section)].filter(Boolean))].map(k=>labels[k]).join(' · ')}</p></div><div class="actions"><button class="btn outline small" data-edit="${esc(i.id)}">Modifier</button><button class="text-link" data-archive="${esc(i.id)}" data-restore="${i.status==='archived'}">${i.status==='archived'?'Restaurer et publier':'Retirer du site'}</button></div></div>`).join('');$$('[data-edit]').forEach(b=>b.onclick=()=>editor(d.items.find(i=>i.id===b.dataset.edit)));$$('[data-archive]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('admin/archive',{id:b.dataset.archive,restore:b.dataset.restore==='true'});await refresh();await render();toast(b.dataset.restore==='true'?'Contenu restauré en brouillon.':'Contenu retiré du site. Il reste disponible dans l’administration.');}catch(err){toast(err.message);b.disabled=false;}});};['content-section','content-status','content-search'].forEach(id=>$('#'+id).oninput=draw);draw();$('#new-item').onclick=()=>editor({kind:({formations:'formation',boutique:'document',bibliotheque:'resource',blog:'article'})[$('#content-section').value]||'resource',status:'draft',modules:[],price:null,language:'Français',placements:[]});
};
function pageName(path){const key=path.split('/')[1];return key?(labels[key]||({'contenu':'Fiche','domaine':'Domaine','recherche':'Recherche','abonnements':'Abonnements'})[key]||key)+(path.split('/')[2]?' / '+decodeURIComponent(path.split('/').slice(2).join('/')):''):'Accueil';}
function adminAccess(){
 const setup=state.setup;main.innerHTML=banner('Administration','Accès privé réservé à l’équipe LEX ASSOCIÉS.')+`<section class="wrap section"><form id="admin-access" class="form-card"><h2>${setup?'Configurer le premier administrateur':'Connexion administrateur'}</h2>${setup?'<p>Le code de configuration se trouve dans le fichier local <b>data/admin-setup-code.txt</b> du projet.</p><label>Code de configuration<input name="setup_code" required autocomplete="off" type="password"></label><label>Nom complet<input name="name" required></label>':''}<label>Adresse e-mail<input name="email" type="email" required autocomplete="username"></label><label>Mot de passe<input name="password" type="password" required minlength="10" autocomplete="${setup?'new-password':'current-password'}"></label><button class="btn">${setup?'Créer mon compte administrateur':'Se connecter'}</button><div class="feedback" role="status"></div></form></section>`;
 $('#admin-access').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=$('button',f);b.disabled=true;try{await api(setup?'admin/setup':'login',Object.fromEntries(new FormData(f)));await refresh();await render();}catch(err){feedback(f,err.message,true);}finally{b.disabled=false;}};
}
const originalEditor=editor;
const previousRubriqueLink=rubriqueLink;
rubriqueLink=function(key,sub){return ['etudiants','professionnels','entreprises'].includes(key)?routeLink(key,sub):previousRubriqueLink(key,sub);};
community=function(key,params){
 const sub=params.get('categorie')||'';const list=state.items.filter(i=>inSection(i,key,sub));
 main.innerHTML=banner(labels[key],{etudiants:'Apprenez, révisez et préparez votre avenir professionnel.',professionnels:'Les ressources utiles à votre métier et à votre pratique.',entreprises:'Formation, documentation et accompagnement des entreprises.'}[key])+`<section class="wrap page-content">${rubriques(key,sub)}<div class="actions" style="margin:30px 0">${button('Explorer les formations','#/formations?public='+enc(labels[key]))}${button(key==='entreprises'?'Demander un devis':'Contacter l’équipe','#/contact?objet='+enc(sub||labels[key]),'outline')}</div>${sub?`<h2>${esc(sub)}</h2><div class="grid">${list.map(card).join('')||empty('Les contenus de cette rubrique seront publiés prochainement.','Le cabinet prépare les ressources de cet espace.')}</div>`:categories[key].map(cat=>{const entries=list.filter(i=>inSection(i,key,cat));return entries.length?`<section class="community-section"><h2>${esc(cat)}</h2><div class="grid">${entries.map(card).join('')}</div></section>`:'';}).join('')||empty('Les contenus seront publiés prochainement.','Sélectionnez une rubrique pour explorer cet espace.')}</section>`;
};
editor=function(source){
 const item=structuredClone(source);originalEditor(item);const f=$('#editor-form');
 f.insertAdjacentHTML('afterbegin','<div class="full notice">Un brouillon est visible uniquement dans cet espace. « Publié » rend le contenu visible dans ses rubriques. Un tarif vide affiche « Tarif à confirmer » ; 0 signifie gratuit. Le nombre de modules est calculé automatiquement.</div>');
 for(const [name,map] of [['kind',adminKinds],['status',publicationLabels]]){const el=f.elements[name];el.innerHTML=Object.entries(map).map(([v,l])=>`<option value="${v}" ${v===item[name]?'selected':''}>${l}</option>`).join('');}
 const categoryInput=f.elements.category;categoryInput.outerHTML='<select name="category" required></select>';
 const placementHTML=`<fieldset class="full placement-editor"><legend>Pages et rubriques où afficher ce contenu</legend><p>Le type de contenu détermine son catalogue principal. Cochez ses rubriques complémentaires, notamment dans les espaces Étudiants, Professionnels et Entreprises.</p>${managedSections.map(key=>`<details ${['etudiants','professionnels','entreprises'].includes(key)?'open':''}><summary>${labels[key]}</summary><div class="placement-options">${categories[key].filter(s=>!/^Tous|^Toutes/.test(s)).map((cat,n)=>`<label><input type="checkbox" name="placement" value="${key}:${n}" data-section="${key}" data-category="${esc(cat)}" ${(item.placements||[]).some(p=>p.section===key&&p.category===cat)?'checked':''}>${esc(cat)}</label>`).join('')}</div></details>`).join('')}</fieldset>`;
 f.insertAdjacentHTML('beforeend',placementHTML);
 const moduleSection=$('#module-editors').parentElement;
 function adapt(){const kind=f.elements.kind.value,key=primarySection[kind];const options=kind==='formation'?domains:(categories[key]||categories[{event:'evenements'}[kind]]||['Général']).filter(x=>!/^Tous|^Toutes/.test(x));const current=f.elements.category.value||item.category;f.elements.category.innerHTML=options.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');for(const name of ['level','trainer','duration','format','language','accessDuration'])f.elements[name].closest('.field').hidden=kind!=='formation';for(const name of ['date','time','location','capacity'])f.elements[name].closest('.field').hidden=kind!=='event';moduleSection.hidden=kind!=='formation';}
 f.elements.kind.onchange=adapt;adapt();
 const save=f.onsubmit;f.onsubmit=async e=>{item.placements=$$('[name="placement"]:checked',f).map(el=>({section:el.dataset.section,category:el.dataset.category}));const b=f.querySelector('button:not([type])');b.disabled=true;try{await save(e);}finally{b.disabled=false;}};
 // Keep the save action after the page-placement choices.
 f.append(f.querySelector('.feedback').parentElement);
 const addControls=()=>{$$('.module-editor').forEach(el=>{if(el.querySelector('.module-order'))return;const row=document.createElement('div');row.className='module-order';row.innerHTML='<button type="button" class="text-link">Monter le module</button><button type="button" class="text-link">Descendre le module</button>';el.prepend(row);row.children[0].onclick=()=>{if(el.previousElementSibling)el.parentElement.insertBefore(el,el.previousElementSibling);};row.children[1].onclick=()=>{if(el.nextElementSibling)el.parentElement.insertBefore(el.nextElementSibling,el);};});};const add=$('#add-module').onclick;$('#add-module').onclick=()=>{add();addControls();};addControls();
};
